def starter_templates(apps, schema_editor):
    """The email prompts were instructions for the AI; they become templates. Each starts with a plain template
    (initial or follow-up) to edit in the admin."""
    EmailPrompt = apps.get_model("pipeline", "EmailPrompt")
    for template in EmailPrompt.objects.all():
        follow_up = template.kind == "follow_up"
        template.subject = FOLLOW_UP_SUBJECT if follow_up else INITIAL_SUBJECT
        template.body = FOLLOW_UP_BODY if follow_up else INITIAL_BODY
        template.save(update_fields=["subject", "body"])


